<template>
  <el-autocomplete
    ref="autocompleteRef"
    v-bind="passInputProps"
    :class="[ns.b(), $attrs.class]"
    :style="$attrs.style"
    :model-value="modelValue"
    :fetch-suggestions="querySearch"
    :value-key="valueKey"
    :placement="placement"
    :teleported="teleported"
    :append-to="appendTo"
    :popper-class="mergedPopperClass"
    :popper-style="popperStyle"
    :debounce="0"
    :is-clear="false"
    fit-input-width
    @update:model-value="handleUpdate"
    @input="handleInput"
    @change="handleChange"
    @focus="handleFocus"
    @blur="handleBlur"
    @clear="handleClear"
    @select="handleSelect"
  >
    <template #default="{ item }">
      <slot name="option" :item="item" :selected="isSelected(item)">
        <div :class="[ns.e('option'), ns.is('selected', isSelected(item))]">
          <el-radio
            :model-value="isSelected(item) ? getOptionValue(item) : undefined"
            :value="getOptionValue(item)"
            aria-hidden="true"
            tabindex="-1"
          >
            {{ getOptionLabel(item) }}
          </el-radio>
        </div>
      </slot>
    </template>

    <template v-if="$slots.prepend" #prepend>
      <slot name="prepend" />
    </template>
    <template v-if="$slots.append" #append>
      <slot name="append" />
    </template>
    <template v-if="$slots.prefix" #prefix>
      <slot name="prefix" />
    </template>
    <template v-if="$slots.suffix" #suffix>
      <slot name="suffix" />
    </template>
  </el-autocomplete>
</template>

<script lang="ts" setup>
import { computed, nextTick, ref } from 'vue'
import { pick } from 'lodash-unified'
import { useNamespace } from '@element-plus/hooks'
import { inputProps } from '@element-plus/components/input'
import ElAutocomplete from '@element-plus/components/autocomplete'
import ElRadio from '@element-plus/components/radio'
import { inputDownEmits, inputDownProps } from './input-down'

import type { AutocompleteInstance } from '@element-plus/components/autocomplete'
import type { InputDownOption, InputDownValue } from './input-down'

defineOptions({
  name: 'ElInputDown',
  inheritAttrs: false,
})

const props = defineProps(inputDownProps)
const emit = defineEmits(inputDownEmits)
const ns = useNamespace('input-down')
const autocompleteRef = ref<AutocompleteInstance>()
let showAllOnFocus = false

const passInputProps = computed(() => pick(props, Object.keys(inputProps)))
const mergedPopperClass = computed(() =>
  props.popperClass ? [ns.e('popper'), props.popperClass] : ns.e('popper')
)

const getOptionValue = (option: InputDownOption): InputDownValue =>
  option[props.valueKey] as InputDownValue

const getOptionLabel = (option: InputDownOption) =>
  String(option[props.labelKey] ?? getOptionValue(option) ?? '')

const isSelected = (option: InputDownOption) =>
  String(getOptionValue(option)) === String(props.modelValue)

const querySearch = (
  query: string,
  callback: (items: InputDownOption[]) => void
) => {
  if (showAllOnFocus) {
    showAllOnFocus = false
    callback(props.options)
    return
  }

  const keyword = query.trim().toLocaleLowerCase()
  if (!keyword) {
    callback(props.options)
    return
  }

  callback(
    props.options.filter((option) => {
      const label = getOptionLabel(option).toLocaleLowerCase()
      const value = String(getOptionValue(option)).toLocaleLowerCase()
      return label.includes(keyword) || value.includes(keyword)
    })
  )
}

const handleUpdate = (value: InputDownValue) => emit('update:modelValue', value)
const handleInput = (value: InputDownValue) => {
  showAllOnFocus = false
  emit('input', value)
}
const handleChange = (value: InputDownValue) => emit('change', value)
const handleFocus = (event: FocusEvent) => {
  showAllOnFocus = true
  emit('focus', event)
}
const handleBlur = (event: FocusEvent) => {
  showAllOnFocus = false
  emit('blur', event)
}
const handleClear = () => {
  emit('clear')
}
const handleSelect = (option: InputDownOption) => {
  showAllOnFocus = false
  emit('select', option)
  nextTick(() => {
    autocompleteRef.value?.close()
    autocompleteRef.value?.getData('')
  })
}

const focus = () => autocompleteRef.value?.focus()
const blur = () => autocompleteRef.value?.blur()
const close = () => {
  autocompleteRef.value?.close()
}

defineExpose({
  autocompleteRef,
  focus,
  blur,
  close,
})
</script>
